function: () => {
  const iframe = document.getElementById('swarmforge-project-plan-frame');
  const doc = iframe.contentDocument;
  const errText = doc.body.innerText;
  const hasSyntaxError = errText.includes('Syntax error');
  const mermaidDivs = doc.querySelectorAll('.mermaid');
  return {
    hasSyntaxError,
    count: mermaidDivs.length,
    svgCounts: Array.from(mermaidDivs).map(d => d.querySelectorAll('svg').length),
    firstFewChars: Array.from(mermaidDivs).slice(0,3).map(d => d.innerHTML.slice(0,80))
  };
}

function: () => {
  const iframe = document.getElementById('swarmforge-project-plan-frame');
  const doc = iframe.contentDocument;
  const mermaidDivs = doc.querySelectorAll('.mermaid');
  return Array.from(mermaidDivs).map((d, i) => ({ i, id: d.id, text: d.innerText.slice(0, 200) }));
}

function: () => {
  const iframe = document.getElementById('swarmforge-project-plan-frame');
  const doc = iframe.contentDocument;
  const mermaidDivs = doc.querySelectorAll('.mermaid');
  return Array.from(mermaidDivs).map((d, i) => ({ i, svgCount: d.querySelectorAll('svg').length, hasSyntaxError: d.innerText.includes('Syntax error') }));
}

function: () => {
  const wraps = document.querySelectorAll('.mermaid-wrap');
  return Array.from(wraps).map((w, i) => ({
    i,
    hasSvg: !!w.querySelector('svg'),
    hasSyntaxErr: w.innerText.includes('Syntax error'),
    panzoomAttached: !!w.__panzoom
  }));
}

function: () => {
  const wrap = document.querySelectorAll('.mermaid-wrap')[0];
  const before = wrap.__panzoom.getZoom();
  return { before };
}

function: () => {
  const wrap = document.querySelectorAll('.mermaid-wrap')[0];
  const rect = wrap.getBoundingClientRect();
  const cx = rect.left + rect.width/2, cy = rect.top + rect.height/2;
  wrap.dispatchEvent(new WheelEvent('wheel', {deltaY: -300, clientX: cx, clientY: cy, bubbles: true, cancelable: true}));
  return { after: wrap.__panzoom.getZoom() };
}

function: () => {
  const wrap = document.querySelectorAll('.mermaid-wrap')[0];
  const rect = wrap.getBoundingClientRect();
  return { left: rect.left, top: rect.top, width: rect.width, height: rect.height };
}

code: async (page) => {
  const before = await page.evaluate(() => document.querySelectorAll('.mermaid-wrap')[0].__panzoom.getZoom());
  await page.mouse.move(71 + 788/2, 1206 + 440/2);
  await page.mouse.wheel(0, -400);
  await page.waitForTimeout(200);
  const after = await page.evaluate(() => document.querySelectorAll('.mermaid-wrap')[0].__panzoom.getZoom());
  return { before, after };
}

code: async (page) => {
  const wrap = page.locator('.mermaid-wrap').first();
  await wrap.scrollIntoViewIfNeeded();
  const box = await wrap.boundingBox();
  const before = await page.evaluate(() => document.querySelectorAll('.mermaid-wrap')[0].__panzoom.getZoom());
  await page.mouse.move(box.x + box.width/2, box.y + box.height/2);
  await page.mouse.wheel(0, -500);
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => document.querySelectorAll('.mermaid-wrap')[0].__panzoom.getZoom());
  return { box, before, after };
}

code: async (page) => {
  const scrollBefore = await page.evaluate(() => window.scrollY);
  await page.mouse.move(400, 100); // outside any diagram, near top
  await page.mouse.wheel(0, 300);
  await page.waitForTimeout(150);
  const scrollAfter = await page.evaluate(() => window.scrollY);
  return { scrollBefore, scrollAfter };
}

